import math

def min_roads_to_demolish(n, q):
    total_roads = n * (n - 1) // 2
    return total_roads - (math.comb(n, q) * (q - 1))

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n, q = map(int, input().split())
        results.append(min_roads_to_demolish(n, q))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
